/**
 * Decodes [instruction] if it belongs to the program (by default [SquadsMultisigProgram.PROGRAM_ID]) and its data
 * starts with the discriminator of one of its instructions, else returns null. Every data byte must be read and
 * there must be enough accounts, so a lucky prefix is not enough.
 */
fun parseSquadsMultisigProgramInstruction(
    instruction: TransactionInstruction,
    programId: SolanaPublicKey = SquadsMultisigProgram.PROGRAM_ID,
): SquadsMultisigProgramInstruction? {
    if (!instruction.programId.bytes.contentEquals(programId.bytes)) return null
    for (parse in PARSERS) parse(instruction.data, instruction.accounts, programId)?.let { return it }
    return null
}

